tier="${1:-full-replay}";[[ "$tier" == fast || "$tier" == full-replay ]]||exit 1;cd "$(dirname "${BASH_SOURCE[0]}")/..";base=b3264fcf3727f7380165eb8de43b76d65b6b2e73;stem=biocortex_ab_track_b_reference_provider_fault_injection_runner_decision_downstream_separation_isolated_lab_implementation_authority_and_resource_binding_decision_v1_pack
