python3 scripts/eval/check_${stem}.py>"$tmp/o";cmp -s scripts/eval/fixtures/${stem}.expected.v0.tsv "$tmp/o"||exit 1;python3 scripts/eval/check_${stem}.py --self-test|grep -qx $'self_test_boundary\tpass'||exit 1
